enum { GSCOLOR_DEFAULT = 0 };
enum { MAX_DISCONNECTS_COUNT = 5 };
static Int MAX_DISCONNECTS[MAX_DISCONNECTS_COUNT] = { 0, 5, 10, 25, 50 };
static bool isInQuickMatchInit = false;
static const Image *quickMatchSelectedImage = 0;
